def factorial(n):
    """
    Recursively calculate factorial for integer n in range 1..50.
    Returns error message string if input invalid.
    """
    try:
        # bool is subclass of int; reject it
        if isinstance(n, bool) or not isinstance(n, int):
            raise TypeError("Input must be an integer.")

        if n < 1 or n > 50:
            raise ValueError("Input must be within the range 1 to 50.")

        # Base case
        if n == 1:
            return 1

        # Recursive case
        return n * factorial(n - 1)

    except (TypeError, ValueError, RecursionError) as error:
        return f"Error: {error}"
```

