using System;
using System.Collections.Generic;
using System.Linq;

namespace RunEliminator
{
 public sealed class Run
 { public char Value {get;} public int Index {get;} public int Length {get;} }

 public static class RunExplorer
 {
   public static IEnumerable<Run> Explore(string text)
   {
     if (string.IsNullOrEmpty(text)) return Enumerable.Empty<Run>();
     int i=0;
     while(i<text.Length) { char c=text[i]; int start=i; while(i<text.Length && text[i]==c) i++; yield return new Run(c,start,i-start); }
   }
   public static IEnumerable<Run> RepeatedRuns(string text) => Explore(text).Where(r=>r.Length>1);
 }

 public enum EliminationMode { CollapseRuns, RemoveRepeatedRunsOnce, IterativelyRemoveRepeatedRuns, RemoveAllRuns }

 public static class Eliminator
 {
