```
#!/usr/bin/env perl
use strict;
use warnings;

# Extract and Analyze Text File Data
# Usage:
#   ./extract_analyze.pl FILE [REGEX]
# If REGEX omitted, extracts all numeric tokens.
# The script prints count, sum, mean, median, min, max, stdev, and per-line extracted values.

sub is_number { return $_ =~ /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/; }

sub analyze {
    my ($values) = @_;
    return () unless @$values;
    my @sorted = sort { $a <=> $b } @$values;
    my $n = scalar @sorted;
    my $sum = 0;
    $sum += $_ for @sorted;
    my $mean = $sum / $n;
    my $median = $n % 2 ? $sorted[$n/2] : ($sorted[$n/2 - 1] + $sorted[$n/2]) / 2;
    my $min = $sorted[0];
    my $max = $sorted[-1];
    my $variance = 0;
    $variance += ($_ - $mean) ** 2 for @sorted;
    my $stddev = sqrt($variance / $n);
    return {
       count => $n,
       sum => $sum,
       mean => $mean,
       median => $median,
       min => $min,
       max => $max,
       stddev => $stddev,
    };
}

my $file = shift @ARGV;
die "Usage: $0 filename [extract_regex]\n" unless $file;
my $extract_re = shift @ARGV;
my $re = defined $extract_re ? $extract_re : qr/(\d+(?:\.\d+)?)/;

open my $fh, '<', $file or die "Cannot open '$file': $!\n";
my @all_numbers;
my @records;
my $line_no = 0;
while (my $line = <$fh>) {
    $line_no++;
    chomp $line;
    next if $line =~ /^\s*$/;
    my @captures = ($line =~ $re);
    next unless @captures;
    my @nums = grep { is_number($_) } @captures;
    next unless @nums;
    push @records, { line => $line_no, text => $line, values => \@nums };
    push @all_numbers, @nums;
}
close $fh;

if (!@all_numbers) { print "No extractable numeric data found in '$file'.\n"; exit 0; }

my $stats = analyze(\@all_numbers);
printf "Extracted data from %s\n", $file;
printf "Lines with data: %d\n", scalar @records;
printf "Numeric values extracted: %d\n\n", $stats->{count};
printf "  Sum:      %.6f\n", $stats->{sum};
printf "  Mean:     %.6f\n", $stats->{mean};
printf "  Median:   %.6f\n", $stats->{median};
printf "  Min:      %.6f\n", $stats->{min};
printf "  Max:      %.6f\n", $stats->{max};
printf "  Std Dev:  %.6f\n\n", $stats->{stddev};

print "Per-line extracted values:\n";
print sprintf("%-6s %-50s %s\n", "Line", "Extracted text", join(", ", @{$r->{values}})) for @records;
```

