func extractIntegerImproved(_ number: Double, _ precision: Int) -> Double {
    guard precision >= 0 else { return number }
    let parts = String(number).split(separator: ".", omittingEmptySubsequences: false)
    guard parts.count >= 2 else { return number.rounded(digits: precision) }

    var integerText = String(parts[0])
