        integerText = "\(abs(integer))"
    }

    var decimal = String(parts[1].prefix(precision))
    if decimal.count < precision { decimal += String(repeating: "0", count: precision - decimal.count) }

    guard precision > 0 else { return Double(integerText) ?? number }
    let out = Double("\(integerText)\.\(decimal)") ?? number
    return out.rounded(digits: precision)
}
