function getPartOfDay(date) {
 try {
  const hour = date.getHours();
  if (hour >= 6 && hour < 12) return 'morning';
  if (hour >= 12 && hour < 17) return 'afternoon';
  if (hour >= 17 && hour < 21) return 'evening';
  return 'night';
 } catch { return 'night'; }
}

formatDateTime:
function formatDateTime(date, use24Hour) {
 try {
   if (!(date instanceof Date) || isNaN(date.getTime())) throw new Error('Invalid date/time object.');
   const hours = date.getHours();
   const minutes = date.getMinutes();
   const seconds = date.getSeconds();
   const pad = (n) => String(n).padStart(2, '0');
   const ampm = hours >= 12 ? 'PM' : 'AM';
   let hourDisplay;
   if (use24Hour) hourDisplay = pad(hours);
   else {
     hourDisplay = pad(hours % 12 === 0 ? 12 : hours % 12);
   }
   const timeText = `${hourDisplay}:${pad(minutes)}:${pad(seconds)}${use24Hour ? '' : ` ${ampm}`}`;
   const dateText = date.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
   return { timeText, dateText };
 } catch (error) {
   return { timeText: 'Time unavailable', dateText: 'Date unavailable', error: error.message || 'Formatting failed' };
 }
}

update:
function update() {
 try {
   const now = new Date();
   if (isNaN(now.getTime())) throw new Error('System date/time is invalid.');
   const part = getPartOfDay(now);
   const formatted = formatDateTime(now, state.use24Hour);
   if (formatted.error) { showError(formatted.error); return; }
   timeDisplay.textContent = formatted.timeText;
   dateDisplay.textContent = formatted.dateText;
   document.body.dataset.theme = part;
   toggleBtn.textContent = state.use24Hour ? 'Switch to 12h' : 'Switch to 24h';
   status.textContent = `Displaying ${state.use24Hour ? '24 hour' : '12 hour'} format • ${part}`;
   status.classList.remove('error');
 } catch (error) { showError(error); }
}

